#nullable enable
using Marten;
using Wolverine.Http;
using HourBooking.Contracts;

namespace HourBooking.Slices.Booking;

/// <summary>
/// Second slice on the Timesheet stream. Reuses MonthGate from book-hours unchanged — the
/// closed-month rule is the same rule, and folding a second copy of it would have been the mistake
/// that per-slice aggregates invites.
///
/// Unlike book-hours there is no membership check: the model's GWTs for this slice never mention
/// EmployeeRemovedFromProject. Correcting hours already booked to a project you have since left is
/// allowed, and that is the model's answer rather than an omission — the rule that refuses the
/// project is on BOOKING, and a correction names a booking that already exists.
/// </summary>
public static class CorrectHoursEndpoint
{
    [WolverinePost("/timesheet/{employeeId}/{month}/bookings/{bookingId}/corrections")]
    public static async Task<IResult> Correct(
        Guid employeeId,
        string month,
        Guid bookingId,
        CorrectHours command,
        IDocumentSession session,
        CancellationToken cancellation)
    {
        // MonthIsClosed. A cross-stream READ of the MonthClosure stream, never a second write.
        var gate = await session.Events.FetchLatest<MonthGate>(
            MonthGate.StreamKey(employeeId, month), cancellation);
        if (gate?.IsClosed == true)
            return Rejections.Problem("MonthIsClosed", "A closed month cannot be corrected. Closed is closed.");

        var stream = await session.Events.FetchForWriting<CorrectHoursState>(
            CorrectHoursState.StreamKey(employeeId, month), cancellation);
        var sheet = stream.Aggregate ?? new CorrectHoursState();

        // BookingNotFound. "Correcting a day+project that was never booked is not a correction."
        var line = sheet.Find(bookingId);
        if (line is null)
            return Rejections.Problem("BookingNotFound",
                "There is no standing booking with that id in this month, so there is nothing to correct.");

        // DailyCapExceeded. Excluding this booking's own hours, because a correction REPLACES them —
        // "a HoursCorrected event carrying the 8 hours, not the 2 difference".
        if (sheet.HoursOnExcluding(line.Date, bookingId) + command.Hours > CorrectHoursState.DailyCap)
            return Rejections.Problem("DailyCapExceeded",
                $"A correction cannot push the day over {CorrectHoursState.DailyCap} hours.");

        stream.AppendOne(new HoursCorrected(
            bookingId, employeeId, month, command.Hours, command.Note, DateTimeOffset.UtcNow));

        await session.SaveChangesAsync(cancellation);
        return Results.NoContent();
    }
}
